/** biome-ignore-all lint/style/noRestrictedImports: Node app */

import { type Telemetry, type TelemetryProperties, TelemetryFactory } from '@servicenow/sdk-build-core/telemetry'
import * as nodeFs from 'node:fs'
import * as nodePath from 'node:path'

export type { TelemetryProperties }

export function createTelemetryClient(sdkDir: string = __dirname, instanceUrl?: URL): Telemetry {
    // Send only the instance host (e.g. `myinstance.service-now.com`), never the full URL.
    const hostname = instanceUrl?.hostname

    return TelemetryFactory.create({
        type: 'node',
        attributes: {
            sdkVersion: readSdkVersion(sdkDir),
            clientName: 'CLI',
            ...(hostname && { hostname }),
        },
    })
}

/**
 * Backwards-compatible wrapper around the capture-based telemetry API.
 *
 * On success it emits `options.event` with any returned data. On failure it emits
 * `options.event` as an error event with the optional `errorData` merged in.
 *
 * The returned client supports the new `capture`/`captureError` methods.
 */
// biome-ignore lint/suspicious/noConfusingVoidType: intentional - lets callers pass callbacks that don't return a value
export async function withTelemetryEvent<T extends TelemetryProperties | void | null>(
    options: { event: string; sdkDir?: string; instanceUrl?: URL; errorData?: TelemetryProperties },
    work: (client: Telemetry) => Promise<T>
): Promise<T> {
    const client = createTelemetryClient(options.sdkDir, options.instanceUrl)
    try {
        const data = await work(client)
        if (data !== null) {
            client.capture(options.event, data ?? undefined)
        }
        return data
    } catch (error) {
        client.captureError(options.event, error, options.errorData)
        throw error
    } finally {
        await client.flush()
    }
}

function readSdkVersion(sdkDir: string): string {
    const rootDir = findPackageRoot(sdkDir)
    if (!rootDir) {
        return ''
    }
    try {
        const raw = nodeFs.readFileSync(nodePath.join(rootDir, 'package.json'), 'utf-8')
        return (JSON.parse(raw).version as string | undefined) ?? ''
    } catch {
        return ''
    }
}

function findPackageRoot(start: string): string | undefined {
    let dir = nodePath.resolve(start)
    while (true) {
        if (nodeFs.existsSync(nodePath.join(dir, 'package.json'))) {
            return dir
        }
        const parent = nodePath.dirname(dir)
        if (parent === dir) {
            return undefined
        }
        dir = parent
    }
}
